'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isInfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var powf = require( '@stdlib/math/base/special/powf' );
var truncf = require( '@stdlib/math/base/special/truncf' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );


// MAIN //

/**
* Rounds a single-precision floating-point number toward zero to `n` digits in base `b`.
*
* @param {number} x - input value
* @param {integer} n - number of digits
* @param {integer} b - base
* @returns {number} rounded value
*
* @example
* var v = truncbf( 3.14159, 2, 10 );
* // returns 3.140000104904175
*
* @example
* var v = truncbf( 3.14159, 3, 10 );
* // returns 3.1410000324249268
*
* @example
* var v = truncbf( 15.0, -1, 10 );
* // returns 10.0
*
* @example
* var v = truncbf( -3.14159, 2, 10 );
* // returns -3.140000104904175
*
* @example
* var v = truncbf( NaN, 2, 10 );
* // returns NaN
*/
function truncbf( x, n, b ) {
	var s;
	var y;

	x = float64ToFloat32( x );

	if ( x === 0.0 || isnanf( x ) || isInfinitef( x ) ) {
		return x;
	}
	if ( b === 0 ) {
		return NaN;
	}

	// Compute scale factor in single precision: s = b^n
	s = powf( float64ToFloat32( b ), float64ToFloat32( n ) );

	// Handle overflow in scale factor
	if ( isInfinitef( s ) ) {
		return x;
	}

	// Multiply by scale, truncate, then divide by scale
	y = truncf( x * s ) / s;

	return float64ToFloat32( y );
}


// EXPORTS //

module.exports = truncbf;
